Here is the commit message:
KVM: arm64: Take the SRCU lock for page table walks in fault
 injection and AT emulation

walk_s1() and kvm_walk_nested_s2() expect to be called while holding
kvm->srcu to guard against memslot changes. While this is generally
the case, __kvm_at_s12() and __kvm_find_s1_desc_level() call into the
respective walkers without taking kvm->srcu.

Fix by acquiring kvm->srcu prior to the table walk in both instances.

Cc: stable@vger.kernel.org
Fixes: 50f77dc87f13 ("KVM: arm64: Populate level on S1PTW SEA injection")
Fixes: be04cebf3e78 ("KVM: arm64: nv: Add emulation of AT S12E{0,1}{R,W}")
Suggested-by: Oliver Upton <oupton@kernel.org>
Signed-off-by: Hyunwoo Kim <imv4bel@gmail.com>
Reviewed-by: Oliver Upton <oupton@kernel.org>
Link: https://patch.msgid.link/aiAZfdeyanIvP8SD@v4bel
Signed-off-by: Marc Zyngier <maz@kernel.org>

Here is the root cause:
The functions __kvm_at_s12() and __kvm_find_s1_desc_level() in arch/arm64/kvm/at.c call page table walkers (kvm_walk_nested_s2() and walk_s1(), respectively) without holding the kvm->srcu lock. These walkers require the SRCU lock to be held to protect against concurrent memslot modifications, which could lead to use-after-free or inconsistent state if memslots are changed during the walk.

Here is the patch:

 int __kvm_at_s12(struct kvm_vcpu *vcpu, u32 op, u64 vaddr)
 {
 	struct kvm_s2_trans out = {};
 	u64 ipa, par;
 	bool write;
 	int ret;

 	/* Do the stage-1 translation */
 	switch (op) {
 	case OP_AT_S12E1R:
 		op = OP_AT_S1E1R;
 		write = false;
 		break;
 	case OP_AT_S12E1W:
 		op = OP_AT_S1E1W;
 		write = true;
 		break;
 	case OP_AT_S12E0R:
 		op = OP_AT_S1E0R;
 		write = false;
 		break;
 	case OP_AT_S12E0W:
 		op = OP_AT_S1E0W;
 		write = true;
 		break;
 	default:
 		WARN_ON_ONCE(1);
 		return 0;
 	}

 	__kvm_at_s1e01(vcpu, op, vaddr);
 	par = vcpu_read_sys_reg(vcpu, PAR_EL1);
 	if (par & SYS_PAR_EL1_F)
 		return 0;

 	/*
 	 * If we only have a single stage of translation (EL2&0), exit
 	 * early. Same thing if {VM,DC}=={0,0}.
 	 */
 	if (compute_translation_regime(vcpu, op) == TR_EL20 ||
 	    !(vcpu_read_sys_reg(vcpu, HCR_EL2) & (HCR_VM | HCR_DC)))
 		return 0;

 	/* Do the stage-2 translation */
 	ipa = (par & GENMASK_ULL(47, 12)) | (vaddr & GENMASK_ULL(11, 0));
 	out.esr = 0;
-	ret = kvm_walk_nested_s2(vcpu, ipa, &out);
+	scoped_guard(srcu, &vcpu->kvm->srcu)
+		ret = kvm_walk_nested_s2(vcpu, ipa, &out);
 	if (ret < 0)
 		return ret;

 	/* Check the access permission */
 	if (!out.esr &&
 	    ((!write && !out.readable) || (write && !out.writable)))
 		out.esr = ESR_ELx_FSC_PERM_L(out.level & 0x3);

 	par = compute_par_s12(vcpu, par, &out);
 	vcpu_write_sys_reg(vcpu, par, PAR_EL1);
 	return 0;
 }


 int __kvm_find_s1_desc_level(struct kvm_vcpu *vcpu, u64 va, u64 ipa, int *level)
 {
 	struct desc_match dm = {
 		.ipa	= ipa,
 	};
 	struct s1_walk_info wi = {
 		.filter	= &(struct s1_walk_filter){
 			.fn	= match_s1_desc,
 			.priv	= &dm,
 		},
 		.as_el0	= false,
 		.pan	= false,
 	};
 	struct s1_walk_result wr = {};
 	int ret;

 	if (is_hyp_ctxt(vcpu))
 		wi.regime = vcpu_el2_e2h_is_set(vcpu) ? TR_EL20 : TR_EL2;
 	else
 		wi.regime = TR_EL10;

 	ret = setup_s1_walk(vcpu, &wi, &wr, va);
 	if (ret)
 		return ret;

 	/* We really expect the S1 MMU to be on here... */
 	if (WARN_ON_ONCE(wr.level == S1_MMU_DISABLED)) {
 		*level = 0;
 		return 0;
 	}

 	/* Walk the guest's PT, looking for a match along the way */
-	ret = walk_s1(vcpu, &wi, &wr, va);
+	scoped_guard(srcu, &vcpu->kvm->srcu)
+		ret = walk_s1(vcpu, &wi, &wr, va);
 	switch (ret) {
 	case -EINTR:
 		/* We interrupted the walk on a match, return the level */
 		*level = dm.level;
 		return 0;
 	case 0:
 		/* The walk completed, we failed to find the entry */
 		return -ENOENT;
 	default:
 		/* Any other error... */
 		return ret;
 	}
 }



